   function[xl]=cal(A)
   [n,n] = size(A);
   [v,d] = eig(A);%求矩阵的特征值和特征向量
   eigenvalue=diag(d);%求对角线向量
   lamda=max(eigenvalue)%求最大特征值
   for i=1:length(A)%求最大特征值对应的序数
      if lamda==eigenvalue(i)
            break;
      end

